<?php

namespace App\Models;

use App\Models\Base\CityModel;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * Table `attachments` (city, from desktop `image + file + profession_meeting_attachment`).
 * Generated by tools/schema/generate-models.php from the approved unified schema v1.1; add behaviour in a
 * hand-written model only after marking it @handwritten.
 */
class Attachment extends CityModel
{
    protected $table = 'attachments';

    protected function casts(): array
    {
        return [
            'city_id' => 'integer',
            'legacy_id' => 'integer',
            'project_id' => 'integer',
            'person_id' => 'integer',
            'profession_meeting_id' => 'integer',
            'attachment_type_id' => 'integer',
            'uploaded_by_account_id' => 'integer',
            'uploaded_at' => 'datetime',
        ];
    }

    public function project(): BelongsTo
    {
        return $this->belongsTo(Project::class, 'project_id');
    }

    public function person(): BelongsTo
    {
        return $this->belongsTo(Person::class, 'person_id');
    }

    public function professionMeeting(): BelongsTo
    {
        return $this->belongsTo(ProfessionMeeting::class, 'profession_meeting_id');
    }

    public function attachmentType(): BelongsTo
    {
        return $this->belongsTo(AttachmentType::class, 'attachment_type_id');
    }

    public function uploadedByAccount(): BelongsTo
    {
        return $this->belongsTo(WebAccount::class, 'uploaded_by_account_id');
    }
}
